  /**
   * allServiceAccountFullAccess iterates over GET /v1/email/exchange/{organizationName}/service/{exchangeService}/account/{primaryEmailAddress}/fullAccess (List full access permissions).
   *
   * It lists the IDs with {@link EmailexchangeApi.listServiceAccountFullAccess}, then gets each object with
   * {@link EmailexchangeApi.getServiceAccountFullAccess}, only when the loop reaches it. An object deleted in the
   * meantime is skipped. Any other error is thrown and stops the loop.
   *
   * The two calls require the IAM action emailExchange:apiovh:service/account/fullAccess/get.
   *
   * @param organizationName - The internal name of your exchange organization
   * @param exchangeService - The internal name of your exchange service
   * @param primaryEmailAddress - Default email for this mailbox
   * @param options - the options of this call: signal, timeout, headers
   * @returns each {@link models.EmailExchangeExchangeAccountFullAccess}, one at a time: loop with `for await`
   * @throws ForbiddenError when the policy lacks an IAM action this call requires
   * @example
   * for await (const item of client.emailexchange.allServiceAccountFullAccess(organizationName, exchangeService, primaryEmailAddress)) console.log(item);
   */
  allServiceAccountFullAccess(
    organizationName: string,
    exchangeService: string,
    primaryEmailAddress: string,
    options?: RequestOptions,
  ): AsyncIterable<models.EmailExchangeExchangeAccountFullAccess> {
    return this._each(
      () =>
        this.listServiceAccountFullAccess(
          organizationName,
          exchangeService,
          primaryEmailAddress,
          options,
        ),
      (listedId) =>
        this.getServiceAccountFullAccess(
          organizationName,
          exchangeService,
          primaryEmailAddress,
          listedId,
          options,
        ),
    );
  }

